parentPort.on('message', async function (msg) {
  if (msg.t === 'resolveResult' || msg.t === 'bridgeResult' || msg.t === 'toolResult' || msg.t === 'replApiResult') {
    var r = pending.get(msg.rid);
    if (r) { pending.delete(msg.rid); r(msg.payload); }
    return;
  }
  // init / toolsUpdate \u{5E42}\u{7B49}\u{4E14}\u{5BB9}\u{5FCD}\u{4E71}\u{5E8F}:\u{53EA}\u{8BA4} epoch \u{66F4}\u{5927}\u{7684}\u{6D88}\u{606F}\u{3002}
  if (msg.t === 'init' || msg.t === 'toolsUpdate') {
    if (typeof msg.epoch === 'number' && msg.epoch <= toolsEpoch) {
      parentPort.postMessage({ t: 'toolsReady', epoch: toolsEpoch });
      return;
    }
    if (typeof msg.epoch === 'number') { toolsEpoch = msg.epoch; }
    var rs = msg.removeServers || [];
    for (var i = 0; i < rs.length; i++) { removeGlobal(rs[i]); serverGlobals.delete(rs[i]); }
    var rt = msg.removeTools || [];
    for (var j = 0; j < rt.length; j++) { removeGlobal(rt[j]); }
    applyTools(msg);
    parentPort.postMessage({ t: 'toolsReady', epoch: toolsEpoch });
    return;
  }
  if (msg.t === 'exec') {
    try {
      var script = new vm.Script(msg.code, { filename: 'repl-tool-code.js' });
      var p = script.runInContext(ctx, { timeout: msg.timeoutMs });
      var rendered = renderReturn(await p);
      parentPort.postMessage({ t: 'done', callId: msg.callId, ok: true, result: rendered.value, images: rendered.images });
    } catch (e) {
      parentPort.postMessage({ t: 'done', callId: msg.callId, ok: false, error: enrichError((e && e.message) || String(e)), images: [] });
    }
  }
});

parentPort.postMessage({ t: 'ready' });
